function validate([queries]) {
  if (queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  for (const query of queries) {
    if (query.length !== 2) return 'Each query is [l, r].';
    const [l, r] = query;
    if (!(1 <= l && l < r && r <= 1000000000)) return 'Each query needs 1 <= l < r <= 10^9.';
  }
  return null;
}

