function minOperations(queries) {
  let total = 0;
  for (const [l, r] of queries) {
    let steps = 0;
    let low = 1;
    let divisions = 1;
    while (low <= r) {
      const high = low * 4 - 1;
      const from = Math.max(l, low);
      const to = Math.min(r, high);
      if (from <= to) {
        steps += (to - from + 1) * divisions;
      }
      low *= 4;
      divisions++;
    }
    total += Math.ceil(steps / 2);
  }
  return total;
}

