function minOperations(queries) {
  let total = 0;
  for (const [l, r] of queries) {
    // count[s] = how many elements still need s more divisions by 4.
    const count = new Array(17).fill(0);
    for (let x = l; x <= r; x++) {
      let s = 0;
      for (let v = x; v > 0; v = Math.floor(v / 4)) s++;
      count[s]++;
    }
    // Simulate: each operation divides the two elements that still need the most divisions.
    let ops = 0;
    for (;;) {
      let top = 16;
      while (top > 0 && count[top] === 0) top--;
      if (top === 0) break;
      count[top]--;
      let second = top;
      while (second > 0 && count[second] === 0) second--;
      count[top - 1]++;
      if (second > 0) { count[second]--; count[second - 1]++; }
      ops++;
    }
    total += ops;
  }
  return total;
}

