function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const LIMIT = 1000000000;
  const query = () => {
    const kind = rand();
    let l, r;
    if (kind < 0.3) {
      l = int(1, 70);
      r = l + int(1, size === 'large' ? 100000 : 8);
    } else if (kind < 0.6) {
      // Straddle a power of 4, where the number of divisions changes.
      const boundary = 4 ** int(1, 14);
      l = Math.max(1, boundary - int(1, size === 'large' ? 5000 : 6));
      r = Math.min(LIMIT, boundary + int(0, size === 'large' ? 5000 : 6));
    } else if (kind < 0.75) {
      r = LIMIT - int(0, 5);
      l = r - int(1, size === 'large' ? 900000000 : 8);
    } else {
      l = int(1, size === 'large' ? LIMIT - 1 : 5000);
      r = size === 'large' ? int(l + 1, LIMIT) : l + int(1, 300);
    }
    if (r <= l) r = l + 1;
    return [l, r];
  };
  const q = size === 'large' ? 2000 : int(1, 3);
  return [Array.from({ length: q }, query)];
}
